const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const africa = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.inList('wld_rgn', ['Africa']));
  const africaGeom = africa.geometry();

  // 2. Data Acquisition & Check
  const modis = ee.ImageCollection('MODIS/061/MCD12Q1');

  const lc2003 = modis.filter(ee.Filter.calendarRange(2003, 2003, 'year')).first();
  const lc2019 = modis.filter(ee.Filter.calendarRange(2019, 2019, 'year')).first();

  // Check if images exist
  const col2003 = modis.filter(ee.Filter.calendarRange(2003, 2003, 'year'));
  const col2019 = modis.filter(ee.Filter.calendarRange(2019, 2019, 'year'));

  const size2003 = await col2003.size().getInfo();
  const size2019 = await col2019.size().getInfo();

  if (size2003 === 0 || size2019 === 0) {
    console.log(`2003 Images: ${size2003}, 2019 Images: ${size2019}`);
    console.log("<answer>C1</answer>");
    return;
  }

  console.log(`2003 Images: ${size2003}, 2019 Images: ${size2019}`);

  // 3. Processing - Extract cropland pixels
  // IGBP: class 12 = Croplands, class 14 = Cropland/Natural Vegetation Mosaic
  const igbp2003 = lc2003.select('LC_Type1');
  const igbp2019 = lc2019.select('LC_Type1');

  const crop2003 = igbp2003.eq(12).or(igbp2003.eq(14));
  const crop2019 = igbp2019.eq(12).or(igbp2019.eq(14));

  // 4. Calculation - Count pixels and convert to area
  const pixelArea = ee.Image.pixelArea();

  const area2003 = crop2003.multiply(pixelArea).divide(1e6); // Convert to km²
  const area2019 = crop2019.multiply(pixelArea).divide(1e6);

  const stats2003 = await area2003.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: africaGeom,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2019 = await area2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: africaGeom,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const cropArea2003 = stats2003.LC_Type1;
  const cropArea2019 = stats2019.LC_Type1;

  // 5. Validation & Final Answer
  if (cropArea2003 === null || cropArea2003 === undefined || 
      cropArea2019 === null || cropArea2019 === undefined ||
      isNaN(cropArea2003) || isNaN(cropArea2019)) {
    console.log("Calculation failed - invalid results");
    console.log("<answer>C3</answer>");
    return;
  }

  const increase = cropArea2019 - cropArea2003;

  console.log(`2003 Cropland: ${cropArea2003.toFixed(0)} km²`);
  console.log(`2019 Cropland: ${cropArea2019.toFixed(0)} km²`);
  console.log(`Increase: ${increase.toFixed(0)} km²`);
  console.log(`Threshold: 400,000 km²`);

  if (increase > 400000) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
